(window.TNQ=window.TNQ||[]).push({"terms":{"자기충족적 예언":{"d":"어떤 기대를 품고 대하면 그 기대에 맞게 실제 결과가 나타나는 현상입니다.","r":[]},"결핍욕구":{"d":"매슬로우가 말한 욕구 중 채워지지 않으면 불편해져 이를 채우려는 하위 욕구입니다.","r":[]},"자기효능감":{"d":"어떤 과제를 해낼 수 있다고 스스로 믿는 정도로 반두라가 제시한 개념입니다.","r":[]},"소거":{"d":"강화를 더 이상 주지 않아 학습된 행동이 점차 줄어드는 과정입니다.","r":["정적강화"]},"정적강화":{"d":"행동 뒤에 바람직한 자극을 주어 그 행동이 늘어나게 하는 것입니다.","r":["소거","타임아웃"]},"타임아웃":{"d":"문제행동이 나왔을 때 강화를 받을 수 있는 상황에서 일정 시간 떼어 놓는 중재입니다.","r":["정적강화"]},"토큰 강화프로그램":{"d":"바람직한 행동에 토큰을 주고 모은 토큰을 보상과 바꾸게 하는 행동수정 방법입니다.","r":["정적강화"]},"체계적 둔감법":{"d":"불안 위계를 만들어 이완 상태에서 약한 자극부터 차례로 직면시키는 치료 기법입니다.","r":[]},"렘(REM)수면":{"d":"빠른 안구운동과 선명한 꿈이 나타나는 수면 단계로 기억 정리와 관련됩니다.","r":[]},"감각등록기":{"d":"외부에서 들어온 정보를 아주 짧은 시간 동안 원형 그대로 잠시 붙잡아 두는 기억 저장소입니다.","r":["작업기억"]},"작업기억":{"d":"정보를 잠시 유지하면서 처리하는 기억 체계로 용량과 시간에 제한이 있습니다.","r":["감각등록기","청킹"]},"청킹":{"d":"낱개의 정보를 의미 있는 덩어리로 묶어 작업기억의 부담을 줄이는 방법입니다.","r":["작업기억"]},"정교화":{"d":"새 정보에 이미 아는 지식이나 예를 덧붙여 의미를 풍부하게 만드는 학습 전략입니다.","r":["조직화"]},"조직화":{"d":"학습 내용을 논리적 관계에 따라 묶고 구조를 잡아 정리하는 학습 전략입니다.","r":["정교화"]},"지연":{"d":"해야 할 일을 필요 이상으로 미루는 행동 경향입니다.","r":[]},"내재적 언어":{"d":"과제를 하면서 스스로에게 하는 속말로 행동을 이끄는 데 쓰입니다.","r":[]},"학습부진":{"d":"지능은 정상인데 심리와 환경 요인 때문에 학업성취가 잠재력에 못 미치는 상태입니다.","r":[]},"중재반응모형":{"d":"증거에 기반한 중재를 단계별로 제공하고 반응을 보아 학습장애를 판별하는 접근입니다.","r":["특정학습장애"]},"특정학습장애":{"d":"지능은 정상이나 읽기, 쓰기, 수학 같은 특정 영역의 학습에 지속적 어려움을 겪는 DSM-5의 진단입니다.","r":["중재반응모형"]}},"notes":{"2차적 문제 발생의 예방을 위해 조기진단과 초기 개입이 필요하다":"학습 실패가 쌓이면 자신감 저하나 정서 문제가 따라오므로 일찍 발견하고 개입해야 합니다.","7±2 단위 정도의 정보를 한 번에 처리할 수 있는 수준이다":"밀러에 따르면 작업기억이 한 번에 다룰 수 있는 항목은 일곱 개 안팎이고 앞뒤로 두 개 차이가 납니다.","DSM-5에서는 특정학습장애라고 명명한다":"DSM-5가 학습장애를 이 이름으로 부르는 것으로, 이전의 읽기장애 등을 하나로 묶은 진단명입니다.","가정의 사회경제적 지위는 부모의 교육적 관심을 매개로 하여 자녀의 학업에 영향을 끼칠 수 있다":"가정 형편은 부모가 교육에 쏟는 관심을 거쳐서 자녀의 학업에 영향을 줍니다.","감각등록기에서 받아들인 정보는 주의를 기울이지 않으면 그대로 사라진다":"감각으로 들어온 정보는 아주 잠깐만 남기 때문에 주의를 주지 않으면 작업기억으로 넘어가지 못합니다.","강화활동 계약의 사용, 규칙과 짝지어진 정적 강화, 문제행동 전환에 대한 강화활동을 포함한다":"강화 중재는 계약, 규칙과 연결한 정적강화, 문제행동을 바른 행동으로 바꾸는 강화로 이루어집니다.","거의 계획을 세우지 않거나 막연한 계획을 세운다":"수동적 준비자는 무엇을 언제 할지 정하지 못해 시험 준비가 체계적이지 못합니다.","계획대로 하지 못하고 시간을 허비하는 이유 중에 지연(procrastination)이 있다":"해야 할 일을 계속 미루다 시간을 놓치는 것이 계획이 어긋나는 흔한 이유입니다.","계획대로 효율적인 방법으로 학습한 자신을 칭찬하는 과정을 통해 성취감과 자신감을 갖도록 할 수 있다":"스스로 보상하는 자기강화로, 잘한 점을 인정하면 성취감이 커져 다음 학습으로 이어집니다.","공부에 대한 반감, 공부 습관 미형성 등이 될 수 있다":"능력이 아니라 공부를 싫어하거나 공부하는 방식이 몸에 배지 않아 생기는 문제입니다.","과제를 수행할 때 자신의 행동을 점검하면서 더 적절한 것으로 바꿔 나가는 것이다":"조절하기는 점검한 결과를 바탕으로 방법을 즉시 고쳐 가며 과제를 이어 가는 일입니다.","과제 완수 단계마다의 사고를 나누어서 각 단계별로 필요한 언어를 내재화하는 과정이 필요하다":"과제를 단계로 쪼개고 단계마다 스스로 해야 할 말을 속으로 되뇌며 익히는 훈련입니다.","과제의 성격에 맞추어 효율적으로 집중력을 향상시킬 수 있다":"과제 유형에 맞는 속말을 쓰면 집중해야 할 곳에 주의를 모을 수 있습니다.","교사와의 관계, 친구와의 관계로 인한 학습부진은 외적환경의 영향이 원인이다":"학습부진의 원인이 학생 밖의 사람 관계에 있다면 외적 환경의 문제로 분류합니다.","교사의 긍정적 기대에 대한 학생의 반응도는 다시 교사의 기대에 영향을 줄 수 있다":"기대가 학생을 바꾸고 학생의 반응이 다시 교사의 기대를 바꾸는 상호작용이 이어집니다.","구체적이고 접근 가능한 과제를 선택한다":"능동형 준비자는 실제로 해낼 수 있는 구체적 과제를 골라 시험 준비를 합니다.","굵은 글씨체의 표제를 질문으로 변형한다":"읽기전략에서 질문하기는 제목을 의문문으로 바꿔 읽는 목적을 세우는 단계입니다.","기대수준보다 낮은 성취를 보인다":"나이와 지능에서 기대되는 수준에 비해 학업 성취가 의미 있게 낮은 상태입니다.","기초학습기능 수행평가체제: 학생이 실제 학습하는 자료 자체를 평가도구로 사용함으로써":"BASA는 학교에서 쓰는 교재 자료를 그대로 평가 도구로 쓰는 방식이라는 문장의 앞부분입니다.","기초학습기능에 대한 수행 정도를 평가한다":"실제 학습 자료로 읽기와 쓰기 같은 기초학습기능을 얼마나 해내는지 측정합니다.","기초학습능력의 결손이나 선수학습의 결손을 확인하고 이를 보완할 수 있는 대안탐색 과정을 도와야 한다":"앞 단계에서 부족한 학습 능력을 찾아내고 채울 방법을 함께 찾도록 돕습니다.","낮은 지능의 문제로 구분할 수 있다":"학습 능력의 문제는 특정 영역의 부족과 전반적인 지능 수준이 낮은 경우로 나뉩니다.","내담자로 하여금 현재 성취수준을 수용하도록 촉진한다":"자신의 지금 성취 수준을 있는 그대로 받아들여야 현실적인 목표를 세울 수 있습니다.","내담자의 비합리적이고 왜곡된 사고를 합리적으로 변화시킨다":"발표를 망칠 것이라는 식의 왜곡된 생각을 근거 있는 생각으로 바꾸는 인지적 개입입니다.","내재적 동기와 외재적 동기로 구분할 수 있다":"활동 자체가 좋아서 하는 동기와 보상이나 벌 같은 바깥 이유로 하는 동기로 나뉩니다.","내재적 언어를 통한 자기통제력 향상은 특히 주의력결핍 과잉행동장애(ADHD) 학생의 자기통제력 향상을 위한 방법으로 제안된다":"충동적으로 행동하기 쉬운 ADHD 학생이 속말로 행동을 멈추고 계획하게 하는 방법입니다.","높은 긴장감과 스트레스로 밤잠을 이루기 힘든 경우에는 30분 정도 가벼운 운동 후 따뜻한 물로 샤워를 한다":"긴장 때문에 잠들기 어려우면 가벼운 운동과 따뜻한 샤워로 몸을 이완시켜 수면을 돕습니다.","다른 친구가 성공적으로 읽기 수행을 하고나서 칭찬받는 장면을 본 후, 자신도 그와 같이 하면 칭찬을 받을 것이라고 기대하고 동기화된다":"남이 칭찬받는 것을 보고 자신도 그럴 것이라 기대하는 대리강화로, 사회인지이론의 설명입니다.","단기기억이 장기기억으로 저장되는 과정은 렘(REM)수면 중에 대부분 이루어진다":"낮에 받아들인 정보가 장기기억에 굳어지는 일은 주로 렘수면 동안에 일어납니다.","단순히 기계적으로 암기하기보다 이해를 수반하는 학습이 효과적이다":"뜻을 이해하며 공부하면 응용 문제에도 쓸 수 있고 기억도 오래 남습니다.","두뇌피로를 풀고, 학습효과를 상승시키는데 효과가 있으므로 30분 정도 자는 것이 좋다":"짧은 낮잠은 지친 뇌를 쉬게 해 이후 학습 효율을 높이므로 길지 않게 30분 정도가 알맞습니다.","막연하고 모호한 형태가 아니라 명확한 형태의 목표가 동기향상에 기여한다":"무엇을 얼마나 할지 분명한 목표여야 자신이 하고 있는 일을 가늠할 수 있어 동기가 높아집니다.","목표설정, 개관, 과제분석 등을 통해 전략 사용을 계획하고 사전지식을 활용하는 것이다":"계획하기는 공부하기 전에 목표를 정하고 과제를 분석하며 이미 아는 것을 불러내는 단계입니다.","목표설정이 행동변화로 연결되기 위해서는 목표의 형태가 적절해야 한다":"목표를 세우기만 해서는 행동이 달라지지 않고 목표가 어떤 모양인지에 달려 있습니다.","목표헌신에 영향을 주는 요인이다":"자기효능감은 목표를 지키려는 헌신의 정도를 좌우하는 요인의 하나입니다.","물리적 환경, 심리적 환경이 원인이 되기도 한다":"소음이나 공간 같은 물리적 조건과 불안한 분위기 같은 심리적 조건도 학습부진을 일으킵니다.","민주가 경험하고 있는 시험불안의 원인을 탐색한다":"불안이 어디서 비롯되는지 살펴야 거기에 맞는 개입 방법을 정할 수 있습니다.","민주의 호소내용은 시험불안에 관한 것임을 알아차리고 시험불안에 대해 다룬다":"상담자는 내담자가 말한 고민이 시험불안임을 파악하고 그것을 상담 주제로 삼습니다.","발표 전, 중, 후에 지속적으로 실시한다":"자기 대화하기는 발표 시점마다 계속하여 스스로에게 긍정적인 말을 건네는 방법입니다.","부모, 형제, 가족 내 정서와 관련이 있다":"가정의 분위기나 가족 간 정서가 안정적이지 않으면 아이가 학업에 집중하기 어렵습니다.","부모나 교사의 칭찬과 격려를 통해 자신감을 향상시킨다":"주변 어른의 인정을 받으면 발표에 대한 자신감이 생겨 불안이 낮아집니다.","빠른 지적 성장에 비해 신체적, 정서적, 사회적 성장이 늦을 수 있다":"영재아는 지적 발달에 비해 다른 영역의 발달이 따라가지 못해 학업에서 어려움을 겪을 수 있습니다.","사회정서적으로 적응하는데 어려움이 있을 수 있다":"공부가 뒤처지면서 친구나 학교생활에서 위축되고 정서적으로 힘들어질 수 있습니다.","상담자가 파악하기 어려운 경우, 교사와 부모의 협조를 얻어서 간접적으로 파악할 수 있다":"선행 학습 수준을 직접 알기 힘들면 학생을 잘 아는 교사와 부모에게 물어 간접적으로 확인합니다.","생물학적 원인에 의한 주의집중력 문제를 가진 내담자는 어릴 때부터 많은 호기심, 높은 에너지 수준을 가지고 있음을 알아야 한다":"타고난 기질에서 오는 주의 문제는 어릴 때부터 호기심과 활동량이 많은 모습으로 나타납니다.","성격, 적성과 흥미의 불일치, 역기능적 사고 등과 관련이 있다":"학생 자신 안의 요인으로, 성격이나 진로와 맞지 않는 공부, 비현실적 생각이 학업에 영향을 줍니다.","성격적 차원, 정서적 차원, 동기적 차원, 행동적 차원의 네 가지로 구성된다":"학습전략검사는 학생의 성격, 정서, 동기, 행동 네 측면에서 학습 전략을 진단합니다.","소속과 애정의 욕구는 결핍욕구에 해당된다":"매슬로우 위계에서 소속과 애정은 자아실현 위의 단계가 아니라 채워져야 하는 결핍욕구입니다.","손발을 가만히 두지 못하거나 부적절한 상황에서 지나치게 뛰어다니거나 기어오른다":"과잉행동 증상으로, 가만히 있어야 할 때에도 몸을 계속 움직입니다.","수행이 요구되는 교실 행동이 유용한 강화활동의 결과로서 명시된다":"행동계약서에는 해야 할 교실 행동과 그것을 했을 때 받을 강화가 구체적으로 적힙니다.","스스로 만든 질문을 통해 평가하기, 문제 푸는 속도를 점검하는 것 등과 같은 방법이 있다":"점검하기는 공부하는 중에 이해가 되고 있는지 스스로 묻고 진행 속도를 살피는 일입니다.","시간계획과 시간관리는 능동적 학습에서 중요하다":"스스로 주도하는 학습에서는 언제 무엇을 할지 정해 두는 것이 학습을 이끄는 틀이 됩니다.","시간계획과 시간관리의 목적은 학습이 효과적으로 이루어지도록 하기 위한 것이다":"시간을 짜는 것 자체가 목표가 아니라 정해진 시간 안에서 학습 효과를 높이려는 수단입니다.","시간을 효율적으로 사용하기 위한 시간배분과 시간조절은 학업성취와 연결된다":"할 일마다 시간을 나누고 진행에 맞춰 조정하는 능력이 학업성취와 관련이 있습니다.","시험불안의 요인인 걱정과 감정 중 어떤 요인이 현재 민주에게 더 큰 영향을 미치고 있는지를 파악한다":"시험불안은 걱정이라는 인지 요인과 정서 요인으로 나뉘므로 어느 쪽이 더 큰지 가려냅니다.","시험성적에서 학령수준에 못 미치는 수행이 나타날 수 있다":"같은 학년 학생에게 기대되는 수준보다 낮은 점수를 받는 형태로 드러납니다.","시험의 난이도와 경험에 따라 학습자에게 적합하고 효과적인 시험준비 전략이 필요하다":"시험이 쉬운지 어려운지와 이전 경험에 맞춰 준비 방법을 달리 선택해야 합니다.","영향을 미치는 중요한 요인은 정교화와 조직화이다":"정보가 장기기억에 잘 저장되려면 의미를 덧붙이는 정교화와 구조를 만드는 조직화가 필요합니다.","웩슬러 지능검사: 언어이해, 시공간, 유동추론, 작업기억, 처리속도의 다섯 가지 지표점수를 제공한다":"K-WISC-Ⅴ는 다섯 영역의 지표점수로 아동의 인지 강점과 약점을 보여 줍니다.","인간의 동기가 결과의 원인을 무엇으로 지각하느냐에 따라서 달라진다고 본다":"성공이나 실패를 능력, 노력, 운 중 무엇 때문이라고 보는지에 따라 이후 동기가 달라진다는 이론입니다.","일시적인 기간에 나타나기도 하고, 장기간에 걸쳐 나타나기도 한다":"학습부진은 한때 지나가는 경우도 있고 오래 이어지는 경우도 있다는 기간상의 특징입니다.","읽는 동안 중요한 개념 혹은 질문에 대한 답이 되는 부분에 표시를 한다":"읽기 단계에서는 앞서 만든 질문의 답이 되는 곳을 찾아 눈에 띄게 표시합니다.","자신이 선택한 행동에 대해서 동기가 높아지고, 선택하지 않은 행동에 대해서는 동기가 낮아진다는 개념이다":"스스로 선택했다는 느낌이 있을 때 동기가 높아지고 강요받으면 떨어진다는 데시와 라이언의 개념입니다.","작업기억에서 한 번에 많은 정보를 처리하기 위한 방법으로 청킹(chunking) 등이 있다":"전화번호를 끊어 외우듯 낱개 정보를 덩어리로 묶으면 작업기억이 더 많은 양을 다룹니다.","작업기억은 정보가 장기기억으로 이동되거나 장기기억 내 지식과 통합될 수 있도록 전달자 기능을 한다":"작업기억은 새 정보를 이미 있는 지식과 연결해 장기기억으로 보내는 중간 통로 구실을 합니다.","잠자기 전에 암기과목을 공부하는 것이 효율적이다":"자기 직전에 외운 내용은 뒤따르는 수면 동안 기억으로 정리되기 쉬워 암기에 유리합니다.","장기기억 속 지식과 의미의 기본단위이다":"명제는 장기기억에 저장되는 지식을 이루는 가장 작은 의미 단위입니다.","장기기억으로 들어가기 위해서는 정보의 심층적인 내용을 이해하고 있어야 한다":"표면만 기억하면 오래 남지 않고 뜻을 깊이 이해해야 장기기억에 저장됩니다.","장애의 발달양상에 대한 충분한 지식을 가지고 그들이 실현해 나가는 과정의 독특성을 이해해야 한다":"학습장애 아동은 장애가 나타나고 변하는 방식과 개인마다 다른 과정을 이해하고 상담해야 합니다.","전반적으로 다시 읽으며 주요 핵심개념을 이해했는가 확인한다":"복습하기는 끝까지 읽은 뒤 전체를 훑으며 핵심 개념을 이해했는지 점검하는 단계입니다.","점차적으로 하락하는 경우 선행학습의 결손이 누적되었을 수도 있다":"성적이 서서히 떨어졌다면 앞 단계에서 이해하지 못한 내용이 쌓여 영향을 줬을 가능성이 있습니다.","정상적인 지적 능력을 가지고 있으나, 심리환경적 요인에 의해 학업이 떨어지는 것을 의미한다":"지능에는 문제가 없지만 심리와 환경 요인 때문에 성적이 오르지 못하는 것을 가리킵니다.","정적강화로부터의 타임아웃은 유용한 강화물의 박탈이 효과적이라는 점을 전제한다":"타임아웃은 아이가 좋아하는 강화물을 일시적으로 얻지 못하게 하는 것이 효과가 있다고 보는 기법입니다.","제한된 시간 내에 원하는 일을 해내는데 있어, 우선순위 정하기는 결정적인 역할을 한다":"시간이 한정되어 있으면 중요하고 급한 일부터 처리하는 순서 정하기가 성패를 가릅니다.","주의집중력 향상을 위한 개입전략으로 활용할 수 있다":"생각을 소리 내어 말하게 하는 훈련으로, 말하는 동안 과제에 주의를 붙들어 둡니다.","주 전략인 인지전략을 보조한다는 측면에서 보조 전략으로 불리기도 한다":"초인지 전략은 암기나 정교화 같은 인지전략이 잘 쓰이도록 돕기 때문에 보조 전략이라고도 합니다.","중요한 부분을 속으로 혹은 소리내어 암송한다":"암송하기는 읽은 내용 중 핵심을 자기 말로 되뇌어 기억을 굳히는 단계입니다.","중요한 시험준비 학습기술이다":"수업 내용을 자기 방식으로 정리하는 노트정리는 시험을 준비할 때 쓰는 핵심 학습기술입니다.","중재반응모형이나 개인내적 처리과정 결함 접근으로도 판별한다":"학습장애는 중재에 대한 반응을 보는 방법이나 개인 안의 정보처리 결함을 찾는 방법으로도 가려냅니다.","지나치게 비구조화 되어 있는 생활환경은 주의집중력 문제의 원인이 되기도 한다":"일과나 규칙이 정해지지 않은 어수선한 환경에서는 아이가 집중하는 습관을 기르기 어렵습니다.","지능이 현저하게 낮지 않으나 학습하고 학업기술을 사용하는데 어려움을 보인다":"지능은 낮지 않은데 배우거나 학업 기술을 쓰는 데 지속적으로 어려움을 겪습니다.","지시를 완수하지 못하고, 학업, 잡일, 작업장에서의 임무 완성에 어려움을 겪는다":"부주의 증상으로, 시작은 해도 끝까지 마무리하지 못해 학업과 직장에서 지장이 생깁니다.","차례를 기다리지 못하거나 종종 다른 사람의 활동을 방해하고 간섭한다":"충동성 증상으로, 순서를 못 기다리고 남의 활동에 끼어듭니다.","캘드웰과 브래들리(B. Caldwell & R. Bradley, 1978)가":"가정환경 검사인 HOME을 캘드웰과 브래들리가 개발했다는 문장의 앞부분입니다.","특정 영역에서의 낮은 학습 능력의 문제와":"학업문제 원인의 하나로, 일부 영역에서만 학습 능력이 낮은 경우를 가리키는 앞부분입니다.","특정 학습 영역을 위한 중재를 받았음에도 불구하고 읽기, 쓰기, 수학 영역 중 적어도 한 가지 영역에서 어려움을 보인다":"도움을 받고도 읽기와 쓰기와 수학 중 하나 이상에서 어려움이 이어지면 진단 기준에 해당합니다.","특정학습장애 아동은 정상수준의 지능을 가지고 있다":"특정학습장애는 지능이 낮아서가 아니라 특정 학습 영역에서 문제가 생긴다는 점이 핵심입니다.","파악하기 위해서는 표준화된 학업성취검사를 활용하는 것이 좋다":"기초학업능력은 같은 기준으로 만들어진 표준화 검사를 써야 객관적으로 알 수 있습니다.","학급중심의 토큰 강화프로그램에서는 하나 이상의 문제가 있는 학급상황이 중재의 목표가 된다":"학급 단위 토큰제는 학급에서 문제가 되는 상황을 정해 그것을 개선하는 데 목적을 둡니다.","학생에 대한 교사의 자기충족적 예언은 학생의 학습노력과 성취 수준에 영향을 줄 수 있다":"교사가 학생에게 거는 기대가 실제로 학생의 노력과 성취를 그 기대에 맞게 바꿔 놓을 수 있습니다.","학습 결손의 누적은 주의집중력에 영향을 미친다":"앞서 배운 내용을 놓친 채 진도가 나가면 수업을 따라가기 힘들어 집중이 흐트러집니다.","학습과제, 연필, 책 등 과제와 활동에 필요한 물건들을 자주 잃어버리거나 일상적인 활동을 잊어버린다":"부주의 증상으로, 필요한 물건을 잃어버리고 해야 할 일을 자주 잊습니다.","학습 내용들 간 논리적 관계를 염두에 두고 내용을 정리하는 것이다":"내용 사이의 포함 관계와 순서를 파악해 개요나 도표로 구조를 잡는 전략입니다.","학습 내용들 간의 논리적 관계를 염두에 두고 내용을 정리하는 것이다":"학습전략에서 조직화는 내용의 위아래와 인과 같은 관계를 따져 틀을 잡아 정리하는 방법입니다.","학습동기는 강화와 소거에 의해 조절될 수 있다":"행동주의에서는 보상을 주면 학습 행동이 늘고 보상을 끊으면 줄어든다고 설명합니다.","학습목표 설정에 대한 학습자의 헌신(commitment)에 영향을 주는 요인은 개인적 요인과 사회적 요인이 있다":"목표를 끝까지 해내려는 의지는 자신의 특성과 주변 사람의 영향 두 갈래의 요인으로 좌우됩니다.","학습의 실패경험으로 낮은 자기효능감의 문제가 나타날 수 있다":"거듭 실패하면 자신이 해낼 수 없다는 믿음이 굳어져 학습 의욕이 더 떨어집니다.","학습자의 학습 취약점들을 보강하는 계획을 세우는데 유용하다":"지능검사 결과로 어느 인지 영역이 약한지 알면 보완할 학습 계획을 짤 수 있습니다.","학습장애가 성인기에도 지속될 수 있다":"학습장애는 아동기에만 있는 문제가 아니라 어른이 되어서도 이어질 수 있습니다.","학습태도가 유사한 것으로 지각된 또래집단에서는 학습에 긍정적 또는 부정적 영향을 끼칠 가능성이 커진다":"자신과 공부 태도가 비슷하다고 느끼는 또래일수록 그 태도가 학습에 더 큰 영향을 줍니다.","학업성취수준이 잠재적인 능력에 미치지 못하고 현격하게 뒤떨어지는 상태를 가리킨다":"학습부진은 타고난 능력으로 기대되는 수준에 비해 성적이 크게 낮은 상태를 뜻합니다.","학업적 자기효능감이 높아지면 학습동기 향상에 도움이 된다":"공부를 해낼 수 있다는 믿음이 커지면 학습하려는 동기도 함께 커집니다.","학업적 자기효능감 척도와 학업적 실패내성 척도로 구성된다":"학업동기검사는 해낼 수 있다는 믿음과 실패를 견디는 정도, 두 척도를 잽니다.","한계가 있기 때문에 많은 정보를 묶어서 기억하거나 처리하는 방법이 제안된다":"작업기억은 한 번에 담는 양이 적어서 정보를 묶어 개수를 줄이는 방법이 쓰입니다.","해당 학년 교과 교육과정에 제시된 최소 수준의 목표에 도달하지 못한 경우":"교과학습부진은 교육과정이 정한 최소한의 성취 기준에도 이르지 못한 상태를 가리킵니다.","행동형, 규범형, 탐구형, 이상형의 네 가지 유형을 제시한다":"학습성격유형검사는 학생을 이 네 가지 유형으로 나누어 학습 방식을 안내합니다.","현재 행동이 가져 올 미래의 결과를 평가하는 기준을 기대와 가치로 본다":"기대가치이론은 성공할 수 있다는 기대와 그 결과를 소중히 여기는 가치로 동기를 설명합니다.","호소문제를 효과적으로 다루기 위해 민주와의 상담관계를 형성하는데 주력한다":"내담자가 믿고 말할 수 있는 관계가 있어야 호소한 문제를 다루는 작업이 가능합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
